INSERT INTO recipes (name, ingredients, description, preparation_time, category, is_public) VALUES
('Bolo de Chocolate', 'farinha de trigo, açúcar, cacau em pó, ovos, leite, fermento, óleo', 'Misture os ingredientes secos, adicione os líquidos, bata até homogeneizar. Asse em forma untada por 40 minutos.', 40, 'sobremesa', TRUE),
('Salada Caesar', 'alface romana, peito de frango, parmesão, croutons, molho caesar', 'Lave e rasgue a alface. Grelhe o frango e corte em tiras. Misture todos os ingredientes e finalize com o molho.', 20, 'salada', TRUE),
('Macarrão à Carbonara', 'macarrão spaghetti, ovos, queijo pecorino, pancetta, pimenta preta', 'Cozinhe o macarrão al dente. Enquanto isso, frite a pancetta. Bata os ovos com o queijo. Misture tudo com o macarrão quente.', 25, 'massa', TRUE),
('Frango Grelhado com Legumes', 'peito de frango, brócolis, cenoura, abobrinha, azeite, alho, limão', 'Tempere o frango com alho, limão e azeite. Grelhe em fogo médio. Cozinhe os legumes no vapor e sirva junto.', 35, 'prato principal', TRUE),
('Sopa de Cebola', 'cebola, caldo de carne, pão, queijo gruyère', 'Refogue as cebolas até caramelizar. Adicione o caldo e cozinhe. Sirva com fatias de pão e queijo gratinado.', 30, 'sopa', TRUE),
('Torta de Limão', 'bolacha maria, manteiga, leite condensado, suco de limão, creme de leite', 'Faça a base com as bolachas trituradas e manteiga. Recheie com a mistura de leite condensado, suco e creme. Leve à geladeira.', 60, 'sobremesa', TRUE),
('Hambúrguer Artesanal', 'carne moída, cebola, alho, pão de hambúrguer, alface, tomate, queijo cheddar', 'Tempere a carne com cebola e alho, modele os hambúrgueres e grelhe. Monte com os acompanhamentos.', 20, 'lanche', TRUE),
('Risoto de Cogumelos', 'arroz arbóreo, cogumelos frescos, caldo de legumes, vinho branco, cebola, parmesão', 'Refogue a cebola, adicione o arroz, vinho e caldo aos poucos. Incorpore os cogumelos e finalize com parmesão.', 45, 'prato principal', TRUE),
